import { type AudioPlayer, createAudioPlayer, setAudioModeAsync } from 'expo-audio';
import * as SecureStore from 'expo-secure-store';
import { useSyncExternalStore } from 'react';
import { Platform } from 'react-native';

// The app's sound effects, generated by scripts/generate-sounds.js.
export type SoundName = 'click' | 'air' | 'open' | 'submit' | 'correct' | 'success' | 'wrong' | 'error';

const SOURCES: Record<SoundName, number> = {
  click: require('../../assets/audio/sfx/click.wav'),
  air: require('../../assets/audio/sfx/air.wav'),
  open: require('../../assets/audio/sfx/open.wav'),
  submit: require('../../assets/audio/sfx/submit.wav'),
  correct: require('../../assets/audio/sfx/correct.wav'),
  success: require('../../assets/audio/sfx/success.wav'),
  wrong: require('../../assets/audio/sfx/wrong.wav'),
  error: require('../../assets/audio/sfx/error.wav'),
};

// How long each sound rings, and how much it matters. While a sound rings, a
// less important one is dropped (an "open" can't cut off a success chime); an
// equal or more important one stops it, so two sounds never overlap.
// `voices` gives a rapid-fire sound several players, so a quick run of clicks
// never waits for the previous one to rewind.
const SPEC: Record<SoundName, { ms: number; rank: number; voices?: number }> = {
  click: { ms: 40, rank: 1, voices: 3 },
  air: { ms: 450, rank: 1 },
  open: { ms: 320, rank: 2 },
  submit: { ms: 450, rank: 2 },
  correct: { ms: 600, rank: 3 },
  wrong: { ms: 500, rank: 3 },
  error: { ms: 360, rank: 4 },
  success: { ms: 1100, rank: 4 },
};

const PREF_KEY = 'sounds_enabled';

let enabled = true;
const listeners = new Set<() => void>();
const players = new Map<SoundName, { voices: AudioPlayer[]; next: number }>();
let current: { name: SoundName; at: number } | null = null;
// Play count per player, so a pending rewind skips a player that was replayed.
const plays = new WeakMap<AudioPlayer, number>();

function warn(err: unknown) {
  if (__DEV__) console.warn('[sounds]', err);
}

const store = {
  get: (): Promise<string | null> =>
    Platform.OS === 'web' ? Promise.resolve(globalThis.localStorage?.getItem(PREF_KEY) ?? null) : SecureStore.getItemAsync(PREF_KEY),
  set: (value: string): Promise<void> =>
    Platform.OS === 'web' ? Promise.resolve(globalThis.localStorage?.setItem(PREF_KEY, value)) : SecureStore.setItemAsync(PREF_KEY, value),
};

// Players are made once and reused for the life of the app, so a sound never
// reloads its file. Turning sounds off frees them.
function load() {
  for (const name of Object.keys(SOURCES) as SoundName[]) {
    if (players.has(name)) continue;
    const voices = Array.from({ length: SPEC[name].voices ?? 1 }, () => {
      const player = createAudioPlayer(SOURCES[name]);
      player.volume = 1;
      return player;
    });
    players.set(name, { voices, next: 0 });
  }
}

function unload() {
  players.forEach(({ voices }) => voices.forEach((player) => player.remove()));
  players.clear();
  current = null;
}

function init() {
  // Respect the silent switch, and mix with music instead of pausing it.
  setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' }).catch(warn);
  try {
    load();
  } catch (err) {
    warn(err);
  }
  store
    .get()
    .then((saved) => {
      if (saved === 'false') applyEnabled(false);
    })
    .catch(warn);
}

function applyEnabled(value: boolean) {
  if (value === enabled) return;
  enabled = value;
  try {
    if (value) load();
    else unload();
  } catch (err) {
    warn(err);
  }
  listeners.forEach((l) => l());
}

/** Plays a sound effect. Safe to call anywhere: it never throws or blocks. */
export function playSound(name: SoundName) {
  if (!enabled) return;
  try {
    const now = Date.now();
    if (current && now < current.at + SPEC[current.name].ms) {
      // The same sound twice in a row (a double-fired handler) plays once.
      if (current.name === name && now < current.at + Math.min(60, SPEC[name].ms)) return;
      if (SPEC[name].rank < SPEC[current.name].rank) return;
      if (current.name !== name) players.get(current.name)?.voices.forEach((p) => p.pause());
    }
    const set = players.get(name);
    if (!set) return;
    const player = set.voices[set.next];
    set.next = (set.next + 1) % set.voices.length;
    // Normally already rewound (below); this only covers a replay mid-sound.
    if (player.currentTime > 0) player.seekTo(0).catch(warn);
    player.play();
    current = { name, at: now };
    // Rewind as soon as it finishes, so the next play starts instantly
    // instead of waiting on a seek.
    const play = (plays.get(player) ?? 0) + 1;
    plays.set(player, play);
    setTimeout(() => {
      if (plays.get(player) !== play) return; // replayed since; leave it running
      player.pause();
      player.seekTo(0).catch(warn);
    }, SPEC[name].ms + 30);
  } catch (err) {
    warn(err);
  }
}

export function setSoundsEnabled(value: boolean) {
  applyEnabled(value);
  store.set(String(value)).catch(warn);
}

const subscribe = (listener: () => void) => {
  listeners.add(listener);
  return () => listeners.delete(listener);
};

/** Whether sound effects are on, kept in sync with the setting. */
export function useSoundsEnabled() {
  return useSyncExternalStore(subscribe, () => enabled);
}

init();
